		if err != nil {
			return "", 0, fmt.Errorf("setup command failed to launch: %w", err)
		}
	}
	testCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	return runVerifyShell(testCtx, repo, flags.Test)
}

